import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Historial","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Historial de búsqueda","slug":"_1-historial-de-busqueda","link":"#_1-historial-de-busqueda","children":[]},{"level":2,"title":"2. Historial de palabras clave","slug":"_2-historial-de-palabras-clave","link":"#_2-historial-de-palabras-clave","children":[]},{"level":2,"title":"3. Asociaciones de consulta","slug":"_3-asociaciones-de-consulta","link":"#_3-asociaciones-de-consulta","children":[]}],"relativePath":"es-ES/user-guide/settings/history.md","filePath":"es-ES/user-guide/settings/history.md","lastUpdated":1792776074000}`),a={name:`es-ES/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="historial" tabindex="-1">Historial <a class="header-anchor" href="#historial" aria-label="Permalink to “Historial”">​</a></h1><p>La página de Historial gestiona la frecuencia de uso por ruta, las palabras clave escritas y las asociaciones confirmadas consulta-destino en tres pestañas independientes: <strong>Historial de búsqueda</strong>, <strong>Historial de palabras clave</strong> y <strong>Asociaciones de consulta</strong>.</p><h2 id="_1-historial-de-busqueda" tabindex="-1">1. Historial de búsqueda <a class="header-anchor" href="#_1-historial-de-busqueda" aria-label="Permalink to “1. Historial de búsqueda”">​</a></h2><p>Registra la frecuencia y recencia con la que abres cada archivo, carpeta o aplicación para afinar el orden entre coincidencias directas equivalentes:</p><ul><li><strong>Desempate por frecuencia con decaimiento</strong>: Los elementos habituales afinan el orden <strong>dentro del mismo grado de coincidencia</strong> con una semivida de 90 días, sin superar nunca a una coincidencia directa exacta de título o nombre.</li><li><strong>Agrupación en la Ventana incrustada</strong>: En los diálogos de archivos, las coincidencias dentro de la carpeta activa se clasifican en &quot;Carpeta actual&quot; y las demás en &quot;Búsqueda global&quot;.</li><li><strong>Filtrado de rutas inexistentes</strong>: Si un archivo ha sido eliminado o movido externamente, se omite de forma automática, evitando enlaces rotos y resultados duplicados.</li><li><strong>Opciones de gestión</strong>: <ul><li><strong>Habilitar historial</strong>: Interruptor general; al desactivarlo se conservan los registros existentes.</li><li><strong>Filtro de búsqueda</strong>: Permite filtrar las entradas visibles.</li><li><strong>Contadores y limpieza</strong>: Elige un umbral y pulsa <strong>Borrar con como máximo N usos</strong>, elimina filas individuales o pulsa <strong>Borrar todo el historial</strong>.</li><li><strong>Actualización en tiempo real</strong>: La lista actualiza automáticamente los contadores tras cada apertura.</li></ul></li></ul><h2 id="_2-historial-de-palabras-clave" tabindex="-1">2. Historial de palabras clave <a class="header-anchor" href="#_2-historial-de-palabras-clave" aria-label="Permalink to “2. Historial de palabras clave”">​</a></h2><p>Memoriza las <strong>cadenas de búsqueda originales</strong> que se hayan usado realmente para ejecutar un resultado o una acción, o para abrir la Ventana principal. Escribir una consulta y cerrar o abandonar la Ventana rápida no la añade:</p><ul><li><strong>Navegación por atajos</strong>: En la Ventana rápida, pulsa <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> para retroceder o avanzar entre consultas recientes. Pulsa <strong><code>Ctrl+Delete</code></strong> para borrar el término activo.</li><li><strong>Contadores y limpieza</strong>: Cada palabra clave muestra cuántas veces se ha usado. Elige un umbral y pulsa <strong>Borrar con como máximo N usos</strong> para eliminar palabras clave poco utilizadas.</li><li><strong>Gestión independiente</strong>: Dispone de su propio interruptor de activación, filtro, eliminación individual y botón de <strong>Borrar todo el historial</strong>.</li></ul><h2 id="_3-asociaciones-de-consulta" tabindex="-1">3. Asociaciones de consulta <a class="header-anchor" href="#_3-asociaciones-de-consulta" aria-label="Permalink to “3. Asociaciones de consulta”">​</a></h2><p>Almacena hábitos confirmados <strong>consulta → ruta de destino</strong> de forma independiente a la frecuencia general:</p><ul><li><strong>Umbral de 3 aperturas orgánicas</strong>: Un elemento solo se recupera por asociación aprendida tras abrirlo de forma orgánica al menos <strong>3 veces</strong> con la misma consulta normalizada, evitando que clics accidentales contaminen búsquedas futuras.</li><li><strong>Sin bucles de retroalimentación</strong>: Las aperturas desde sugerencias aprendidas no inflan contadores no confirmados y aparecen siempre detrás de las coincidencias directas.</li><li><strong>Limpieza independiente</strong>: Filtra, elimina asociaciones individuales o bórralas todas sin reiniciar la frecuencia de uso por ruta.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};